const MS_PER_MINUTE = 60_000;

/**
 * Formats a duration for people, rounded to the nearest minute.
 * Examples: "1 h 30 min", "2 h", "38 min", "0 min" (under 30 seconds).
 */
export function formatDuration(ms: number): string {
  if (!Number.isFinite(ms) || ms < 0) {
    throw new RangeError(`Duration must be a non-negative number, got ${ms}`);
  }

  const totalMinutes = Math.round(ms / MS_PER_MINUTE);
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;

  if (hours === 0) return `${minutes} min`;
  if (minutes === 0) return `${hours} h`;
  return `${hours} h ${minutes} min`;
}

