import { formatDuration } from "./duration";
import type { Trail } from "./trails";

/** One line per trail for the weekly email. */
export function summarize(trails: Trail[]): string[] {
  return trails.map(
    (trail) =>
      `${trail.name} (${trail.region}): ${trail.distanceKm} km, best ${formatDuration(trail.bestTimeMs)}`,
  );
}

