import { expect, test } from "bun:test";
import { formatDuration } from "../src/duration";

const MIN = 60_000;
const HOUR = 60 * MIN;

test("formats hours and minutes", () => {
  expect(formatDuration(HOUR + 30 * MIN)).toBe("1 h 30 min");
  expect(formatDuration(3 * HOUR + 5 * MIN)).toBe("3 h 5 min");
});

test("formats minutes only below one hour", () => {
  expect(formatDuration(38 * MIN)).toBe("38 min");
  expect(formatDuration(59 * MIN)).toBe("59 min");
});

test("omits minutes for whole hours", () => {
  expect(formatDuration(2 * HOUR)).toBe("2 h");
});

test("rounds to the nearest minute", () => {
  expect(formatDuration(0)).toBe("0 min");
  expect(formatDuration(29_999)).toBe("0 min");
  expect(formatDuration(30_000)).toBe("1 min");
  expect(formatDuration(38 * MIN + 29_000)).toBe("38 min");
  // Rounding can carry into the next hour.
  expect(formatDuration(HOUR - 20_000)).toBe("1 h");
});

test("rejects negative and non-finite durations", () => {
  expect(() => formatDuration(-1)).toThrow(RangeError);
  expect(() => formatDuration(Number.NaN)).toThrow(RangeError);
  expect(() => formatDuration(Number.POSITIVE_INFINITY)).toThrow(RangeError);
});

